import hashlib
import json
import re
import shutil
import subprocess
import zipfile
from datetime import datetime, timezone
from pathlib import Path
from xml.etree import ElementTree as ET

ROOT = Path('/root/papers/all')
WORK = Path('/root/papers/organizer_work')
MANIFEST_PATH = Path('/root/papers/classification_manifest.json')
DESTINATIONS = {'LLM', 'trapped_ion_and_qc', 'black_hole', 'DNA', 'music_history'}
NS = {
    'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main',
    'cp': 'http://schemas.openxmlformats.org/package/2006/metadata/core-properties',
    'dc': 'http://purl.org/dc/elements/1.1/',
    'dcterms': 'http://purl.org/dc/terms/',
    'a': 'http://schemas.openxmlformats.org/drawingml/2006/main',
    'p': 'http://schemas.openxmlformats.org/presentationml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
    'pr': 'http://schemas.openxmlformats.org/package/2006/relationships',
}


def sha256(path):
    h = hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()


def xml_root(data):
    return ET.fromstring(data)


def text_from_xml(data, tags=None):
    root = xml_root(data)
    if tags:
        values = []
        for tag in tags:
            values.extend((node.text or '').strip() for node in root.findall('.//' + tag) if (node.text or '').strip())
        return '\n'.join(values)
    return ' '.join(t.strip() for t in root.itertext() if t and t.strip())


def normalize(text):
    text = text.replace('\r', '\n').replace('\x00', ' ')
    text = re.sub(r'[ \t]+', ' ', text)
    text = re.sub(r'\n{3,}', '\n\n', text)
    return text.strip()


def excerpt(text, limit=18000):
    text = normalize(text)
    if len(text) <= limit:
        return text
    first = int(limit * 0.65)
    last = limit - first
    return text[:first] + '\n...[middle omitted]...\n' + text[-last:]


def run_cmd(args, timeout=120):
    try:
        result = subprocess.run(args, capture_output=True, text=True, timeout=timeout)
        return result.returncode, result.stdout, result.stderr.strip()
    except Exception as exc:
        return None, '', f'{type(exc).__name__}: {exc}'


def parse_pdf(path, outdir):
    warnings = []
    status = 'ok'
    code, info, err = run_cmd(['pdfinfo', str(path)])
    metadata = {}
    if code == 0:
        for line in info.splitlines():
            if ':' in line:
                key, value = line.split(':', 1)
                metadata[key.strip()] = value.strip()
    else:
        warnings.append('pdfinfo failed: ' + err)
    code, text, err = run_cmd(['pdftotext', '-layout', str(path), '-'], timeout=180)
    if code != 0:
        status = 'extraction_failed'
        warnings.append('pdftotext failed: ' + err)
        text = ''
    text = normalize(text)
    if len(text) < 200:
        status = 'preview_required' if status == 'ok' else status
        warnings.append('text extraction empty or very short')
    page_count = metadata.get('Pages', '')
    out = outdir / (path.name + '.txt')
    out.write_text(text, encoding='utf-8', errors='replace')
    representative = excerpt(text)
    return {
        'extractor': ['pdfinfo', 'pdftotext'],
        'extraction_status': status,
        'warnings': warnings,
        'metadata': metadata,
        'page_count': page_count,
        'text_path': str(out),
        'representative_text': representative,
    }


def docx_parts(zf):
    names = [n for n in zf.namelist() if n.startswith('word/') and n.endswith('.xml')]
    names.sort(key=lambda n: (0 if n == 'word/document.xml' else 1, n))
    return names


def parse_docx(path, outdir):
    warnings = []
    chunks = []
    metadata = {}
    try:
        with zipfile.ZipFile(path) as zf:
            for name in docx_parts(zf):
                try:
                    data = zf.read(name)
                    root = xml_root(data)
                    paragraphs = []
                    for p in root.findall('.//w:p', NS):
                        parts = []
                        for node in p.iter():
                            if node.tag == '{%s}t' % NS['w'] and node.text:
                                parts.append(node.text)
                            elif node.tag == '{%s}tab' % NS['w']:
                                parts.append('\t')
                        value = ''.join(parts).strip()
                        if value:
                            paragraphs.append(value)
                    if paragraphs:
                        chunks.append(f'[{name}]\n' + '\n'.join(paragraphs))
                except Exception as exc:
                    warnings.append(f'{name}: {type(exc).__name__}: {exc}')
            if 'docProps/core.xml' in zf.namelist():
                root = xml_root(zf.read('docProps/core.xml'))
                for key, tag in [('title', 'dc:title'), ('subject', 'dc:subject'), ('creator', 'dc:creator'), ('keywords', 'cp:keywords'), ('description', 'dc:description')]:
                    node = root.find('.//' + tag, NS)
                    if node is not None and node.text:
                        metadata[key] = node.text.strip()
    except Exception as exc:
        warnings.append(f'zip parse failed: {type(exc).__name__}: {exc}')
    text = normalize('\n\n'.join(chunks))
    status = 'ok' if text else 'extraction_failed'
    if not text:
        warnings.append('no text extracted')
    out = outdir / (path.name + '.txt')
    out.write_text(text, encoding='utf-8', errors='replace')
    return {
        'extractor': ['zipfile', 'OOXML'],
        'extraction_status': status,
        'warnings': warnings,
        'metadata': metadata,
        'page_count': None,
        'text_path': str(out),
        'representative_text': excerpt(text),
    }


def slide_number(name):
    m = re.search(r'slide(\d+)\.xml$', name)
    return int(m.group(1)) if m else 10**9


def parse_pptx(path, outdir):
    warnings = []
    chunks = []
    metadata = {}
    try:
        with zipfile.ZipFile(path) as zf:
            if 'docProps/core.xml' in zf.namelist():
                root = xml_root(zf.read('docProps/core.xml'))
                for key, tag in [('title', 'dc:title'), ('subject', 'dc:subject'), ('creator', 'dc:creator'), ('keywords', 'cp:keywords'), ('description', 'dc:description')]:
                    node = root.find('.//' + tag, NS)
                    if node is not None and node.text:
                        metadata[key] = node.text.strip()
            slide_names = sorted((n for n in zf.namelist() if re.search(r'ppt/slides/slide\d+\.xml$', n)), key=slide_number)
            for index, name in enumerate(slide_names, 1):
                root = xml_root(zf.read(name))
                texts = [(n.text or '').strip() for n in root.findall('.//a:t', NS) if (n.text or '').strip()]
                slide_chunk = [f'[Slide {index}]'] + texts
                rels_name = 'ppt/slides/_rels/' + Path(name).name + '.rels'
                if rels_name in zf.namelist():
                    relroot = xml_root(zf.read(rels_name))
                    for rel in relroot.findall('.//pr:Relationship', NS):
                        target = rel.attrib.get('Target', '')
                        if 'notesSlide' in target:
                            notes_name = 'ppt/slides/' + target.lstrip('../')
                            notes_name = str(Path('ppt/slides').joinpath(target.replace('../', '')))
                            if notes_name in zf.namelist():
                                notesroot = xml_root(zf.read(notes_name))
                                notes = [(n.text or '').strip() for n in notesroot.findall('.//a:t', NS) if (n.text or '').strip()]
                                if notes:
                                    slide_chunk += ['[Speaker notes]'] + notes
                chunks.append('\n'.join(slide_chunk))
    except Exception as exc:
        warnings.append(f'zip/OOXML parse failed: {type(exc).__name__}: {exc}')
    text = normalize('\n\n'.join(chunks))
    status = 'ok' if text else 'extraction_failed'
    if not text:
        warnings.append('no slide text extracted')
    out = outdir / (path.name + '.txt')
    out.write_text(text, encoding='utf-8', errors='replace')
    return {
        'extractor': ['zipfile', 'OOXML'],
        'extraction_status': status,
        'warnings': warnings,
        'metadata': metadata,
        'slide_count': len(chunks),
        'text_path': str(out),
        'representative_text': excerpt(text),
    }


def make_record(path):
    rel = path.relative_to(ROOT).as_posix()
    stat = path.stat()
    record = {
        'source_path': str(path),
        'relative_path': rel,
        'basename': path.name,
        'extension': path.suffix.lower(),
        'size': stat.st_size,
        'mtime_ns': stat.st_mtime_ns,
        'sha256': sha256(path),
        'assigned_subject': None,
        'assignment_status': 'unclassified',
        'intended_destination': None,
        'move_status': 'not_started',
        'final_path': None,
        'verification': None,
    }
    file_out = WORK / 'extracted'
    file_out.mkdir(parents=True, exist_ok=True)
    if path.suffix.lower() == '.pdf':
        record.update(parse_pdf(path, file_out))
    elif path.suffix.lower() == '.docx':
        record.update(parse_docx(path, file_out))
    elif path.suffix.lower() == '.pptx':
        record.update(parse_pptx(path, file_out))
    else:
        try:
            data = path.read_text(encoding='utf-8', errors='replace')
            out = file_out / (path.name + '.txt')
            out.write_text(data, encoding='utf-8')
            record.update({'extractor': ['text'], 'extraction_status': 'ok', 'warnings': [], 'metadata': {}, 'text_path': str(out), 'representative_text': excerpt(data)})
        except Exception as exc:
            record.update({'extractor': [], 'extraction_status': 'extraction_failed', 'warnings': [str(exc)], 'metadata': {}, 'text_path': None, 'representative_text': ''})
    return record


def eligible_files():
    paths = []
    for p in ROOT.rglob('*'):
        if not p.is_file():
            continue
        if any(part in DESTINATIONS for part in p.relative_to(ROOT).parts):
            continue
        paths.append(p)
    return sorted(paths, key=lambda p: p.relative_to(ROOT).as_posix())


def main():
    WORK.mkdir(parents=True, exist_ok=True)
    old = {}
    if MANIFEST_PATH.exists():
        try:
            prior = json.loads(MANIFEST_PATH.read_text(encoding='utf-8'))
            old = {r.get('sha256'): r for r in prior.get('records', []) if r.get('sha256')}
        except Exception:
            old = {}
    records = []
    for path in eligible_files():
        record = make_record(path)
        prior = old.get(record['sha256'])
        if prior and prior.get('move_status') == 'moved_verified':
            for key in ('assigned_subject', 'assignment_status', 'intended_destination', 'move_status', 'final_path', 'verification'):
                record[key] = prior.get(key)
        records.append(record)
    manifest = {
        'manifest_version': 1,
        'created_at': datetime.now(timezone.utc).isoformat(),
        'source_root': str(ROOT),
        'destination_names': sorted(DESTINATIONS),
        'record_count': len(records),
        'records': records,
    }
    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2, ensure_ascii=False), encoding='utf-8')
    catalog = WORK / 'catalog.txt'
    with catalog.open('w', encoding='utf-8') as f:
        for r in records:
            f.write('\n' + '=' * 100 + '\n')
            f.write(f"FILE: {r['relative_path']}\nSIZE: {r['size']}\nSTATUS: {r.get('extraction_status')}\nMETADATA: {json.dumps(r.get('metadata', {}), ensure_ascii=False)}\n")
            f.write('-' * 100 + '\n')
            f.write(r.get('representative_text', '') + '\n')
    print(f'Processed {len(records)} files')
    print(f'Manifest: {MANIFEST_PATH}')
    print(f'Catalog: {catalog}')
    for status in sorted({r.get('extraction_status') for r in records}):
        print(status, sum(r.get('extraction_status') == status for r in records))


if __name__ == '__main__':
    main()
