import hashlib
import json
import shutil
from pathlib import Path

MANIFEST_PATH = Path('/root/papers/classification_manifest.json')
ROOT = Path('/root/papers/all')
DESTINATIONS = ['LLM', 'trapped_ion_and_qc', 'black_hole', 'DNA', 'music_history']


def sha256(path):
    h = hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()


def choose_destination(subject, basename, relative_path):
    direct = ROOT / subject / basename
    if not direct.exists():
        return direct
    collision_dir = ROOT / subject / '_source_collisions' / Path(relative_path).parent
    collision_dir.mkdir(parents=True, exist_ok=True)
    candidate = collision_dir / basename
    if candidate.exists():
        raise FileExistsError(f'collision exists: {candidate}')
    return candidate


def main():
    manifest = json.loads(MANIFEST_PATH.read_text(encoding='utf-8'))
    for subject in DESTINATIONS:
        (ROOT / subject).mkdir(exist_ok=True)
    failures = []
    for record in manifest['records']:
        if record.get('move_status') == 'moved_verified':
            continue
        source = Path(record['source_path'])
        subject = record.get('assigned_subject')
        if not subject or subject not in DESTINATIONS:
            record['move_status'] = 'unresolved'
            record['verification'] = {'ok': False, 'reason': 'missing or invalid subject assignment'}
            failures.append(record['basename'])
            continue
        try:
            if not source.exists():
                raise FileNotFoundError(source)
            if source.stat().st_size != record['size'] or sha256(source) != record['sha256']:
                raise RuntimeError('source identity changed before move')
            destination = choose_destination(subject, record['basename'], record['relative_path'])
            shutil.move(str(source), str(destination))
            destination_hash = sha256(destination)
            verification = {
                'ok': destination.exists() and not source.exists() and destination.name == record['basename'] and destination.stat().st_size == record['size'] and destination_hash == record['sha256'],
                'source_absent': not source.exists(),
                'destination_exists': destination.exists(),
                'basename_preserved': destination.name == record['basename'],
                'size_matches': destination.stat().st_size == record['size'],
                'sha256': destination_hash,
            }
            if not verification['ok']:
                raise RuntimeError('post-move verification failed')
            record['move_status'] = 'moved_verified'
            record['final_path'] = str(destination)
            record['intended_destination'] = str(destination)
            record['verification'] = verification
        except Exception as exc:
            record['move_status'] = 'unresolved'
            record['verification'] = {'ok': False, 'reason': f'{type(exc).__name__}: {exc}'}
            failures.append(record['basename'])
        MANIFEST_PATH.write_text(json.dumps(manifest, indent=2, ensure_ascii=False), encoding='utf-8')
    manifest['move_summary'] = {
        'moved_verified': sum(r.get('move_status') == 'moved_verified' for r in manifest['records']),
        'unresolved': sum(r.get('move_status') == 'unresolved' for r in manifest['records']),
    }
    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2, ensure_ascii=False), encoding='utf-8')
    print(json.dumps(manifest['move_summary']))
    if failures:
        print('Failures:', ', '.join(failures))
        raise SystemExit(1)


if __name__ == '__main__':
    main()
